const crypto = require('crypto');
const { URL } = require('url');
const input = $json.body ?? $json;
const limits = { request_id: 36, status_token: 64, contact_name: 200, company_name: 200, email: 254, whatsapp: 32, city: 120, state: 80, google_maps_url: 2000, keyword: 200, campaign_id: 128, privacy_policy_version: 100 };
for (const key of ['request_id','status_token','contact_name','company_name','email','whatsapp','city','state','keyword','campaign_id','privacy_policy_version']) {
  if (typeof input[key] !== 'string' || !input[key].trim() || input[key].trim().length > limits[key]) throw new Error(`Missing, invalid, or oversized field: ${key}`);
}
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(input.request_id)) throw new Error('Invalid request ID');
if (!/^[a-f0-9]{64}$/.test(input.status_token)) throw new Error('Invalid status capability');
if (input.privacy_acknowledged !== true || typeof input.marketing_consent !== 'boolean') throw new Error('Privacy acknowledgement and explicit marketing choice are required');
if (input.website && String(input.website).trim()) return { json: { is_bot: true, request_id: input.request_id, status_token: input.status_token } };
const email = input.email.trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Invalid email');
const whatsapp = input.whatsapp.replace(/[^+\d]/g, '');
if (whatsapp.length < 8 || whatsapp.length > 20) throw new Error('Invalid WhatsApp number');
let mapsUrl = null;
if (typeof input.google_maps_url === 'string' && input.google_maps_url.trim()) {
  const parsed = new URL(input.google_maps_url.trim());
  const host = parsed.hostname.toLowerCase();
  if (parsed.protocol !== 'https:' || !(host === 'google.com' || host.endsWith('.google.com') || host === 'maps.app.goo.gl' || host === 'goo.gl')) throw new Error('google_maps_url must be an HTTPS Google Maps URL');
  mapsUrl = parsed.toString();
}
if (input.contact_name.trim().length < 2 || input.company_name.trim().length < 2 || input.city.trim().length < 2 || input.keyword.trim().length < 2) throw new Error('Name, city and keyword fields are too short');
const clean = { request_id: input.request_id, status_token: input.status_token, status_token_hash: crypto.createHash('sha256').update(input.status_token).digest('hex'), contact_name: input.contact_name.trim(), company_name: input.company_name.trim(), email, whatsapp, city: input.city.trim(), state: input.state.trim().toUpperCase(), google_maps_url: mapsUrl, keyword: input.keyword.trim(), campaign_id: input.campaign_id.trim(), privacy_acknowledged: true, privacy_policy_version: input.privacy_policy_version.trim(), marketing_consent: input.marketing_consent, consent_at: new Date().toISOString(), is_bot: false };
const fingerprintFields = { ...clean };
delete fingerprintFields.status_token;
delete fingerprintFields.status_token_hash;
delete fingerprintFields.consent_at;
delete fingerprintFields.is_bot;
const canonical = JSON.stringify(fingerprintFields);
const idempotencyKey = crypto.createHash('sha256').update(`${clean.campaign_id}\n${email}`).digest('hex');
const fingerprint = crypto.createHash('sha256').update(canonical).digest('hex');
return { json: { ...clean, idempotency_key: idempotencyKey, payload_fingerprint: fingerprint } };
